head.script:
scwin.onpageload = function() {
	var frameId = $p.getFrameId() || $p.getParameter("w2xPath");
	console.log("onpageload - " + frameId + " Frame");
};
scwin.btn_openTabControlIFrame_onclick = function(e) {
	if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
	var popupId = "tabControl_scope_WPFF-221_(WSQ-3504)_tabControl";
	var opts = {
		"id": popupId,
		"type": "iframePopup",
		"width": "560px",
		"height": "530px",
		"top": "100px",
		"left": "100px",
		"popupName": popupId,
		"modal": false,
		"title": popupId
	};
	$p.openPopup("/sample/common_link/tabControl_scope_WPFF-221_(WSQ-3504)_tabControl.xml", opts);
};
